query GetPublicWorkspaceDataByDomain($origin: String!) {
  getPublicWorkspaceDataByDomain(origin: $origin) {
    id
    logo
    displayName
    workspaceUrls {
      ...WorkspaceUrlsFragment
      __typename
    }
    authProviders {
      sso {
        id
        name
        type
        status
        issuer
        __typename
      }
      google
      magicLink
      password
      microsoft
      __typename
    }
    authBypassProviders {
      google
      password
      microsoft
      __typename
    }
    __typename
  }
}

fragment WorkspaceUrlsFragment on WorkspaceUrls {
  subdomainUrl
  customUrl
  __typename
}
